fn main(){let p=211u64;let pow=|x:u64,n:u32|{let mut v=1;for _ in 0..n{v=v*x%p}v};let mut fb=vec![];for x in 0..p{let v=(pow(x,7)+pow(x,3)+12*x+1)%p;if let Some(y)=(0..=p/2).find(|&y|y*y%p==v){fb.push((x,y));}}let m=fb.len();let selected:Vec<_>=(0..36).map(|j|fb[(m/2+j)%m]).collect();let branch:Vec<_>=selected.iter().filter(|z|z.1==0).collect();println!("g3_p211_catalogue_size={m}\nrotated_H36_branch_anchors={}\nbranch_points={branch:?}\neffective_columns={}",branch.len(),38-branch.len());}
